/* CustomsMapper.updateEidLinked : TB_EDI_LINKED 수정 */
	UPDATE TB_EDI_LINKED SET


		   EDI_STATUS = 'ERROR'


		   EDI_STATUS = 'READY'


		  ,EDI_SEND_DATE = DATEADD(HOUR, ${gmtTime}, GETDATE())
	WHERE EDI_JOB_NO = #{EDI_JOB_NO}

/* CustomsMapper.updateUnmanagementDate : 별도관리해제신고 일자 수정 */
	UPDATE TB_ECM_OD_ADDITIONAL SET
		   UNMANAGEMENT_DATE = #{issueDate}
	WHERE SPECIAL_ITEM_DOC_NO = #{ediDocNo}

mapper.select:
/* CustomsMapper.selectSendAbnormalitiesAbnormal : 하기결과이상보고 대상 조회 */ SELECT od.HBL_NO ,od.PIECES ,od.GWT ,od.HSN ,od.MRN ,od.LINE_CODE ,abnormal.VESSEL_FLIGHT ,od.MBL_NO ,od.MSN ,od.DEST_CODE ,od.OD_JOB_NO ,CONVERT(VARCHAR(8), od.AR_DATE, 112) AS AR_DATE ,abnormal.ABNORMAL_CODE ,abnormal.PIECES AS PIECES_ABNORMAL ,abnormal.GWT AS GWT_ABNORMAL ,abnormal.DISC_WH_CODE ,abnormal.MRN AS MRN_ABNORMAL ,abnormal.MSN AS MSN_ABNORMAL ,abnormal.SEQ_NO_ID ,CONVERT(VARCHAR(8), abnormal.AR_DATE, 112) AS AR_DATE_ABNORMAL ,CASE abnormal.ABNORMAL_CODE WHEN 'MFN' THEN 2 ELSE 1 END AS SORT_SEQ_NO ,(SELECT OD_JOB_NO FROM TB_ECM_OD_ABNORMAL WHERE OD_JOB_NO = od.OD_JOB_NO AND SEQ_NO_ID = 1 AND SEND_DATE IS NULL) AS UPDATE_OD_JOB_NO ,( SELECT TOP 1 A.POD_JOB_NO FROM( SELECT POD_JOB_NO FROM TB_ECM_POD WHERE OD_JOB_NO = od.OD_JOB_NO AND POD_STATUS = 'ECM160' UNION ALL SELECT POD_JOB_NO FROM TB_ECM_POD_02 WHERE OD_JOB_NO = od.OD_JOB_NO AND POD_STATUS = 'ECM160' ) A ) AS ECM160_POD_JOB_NO FROM TB_ECM_OD od INNER JOIN TB_ECM_OD_ABNORMAL abnormal ON abnormal.OD_JOB_NO = od.OD_JOB_NO AND abnormal.SEND_DATE IS NULL WHERE od.MASTER_OD_JOB_NO = #{masterOdJobNo} AND(
(abnormal.OD_JOB_NO = #{item.odJobNo} AND abnormal.SEQ_NO_ID = #{item.seqNoId})
) ORDER BY od.OD_JOB_NO, SORT_SEQ_NO

/* CustomsMapper.selectSendBmsInPlanAbnormalitiesAbnormal : 하기결과이상보고 대상 조회(반입예정데이터) */ SELECT bip.BL_NO AS HBL_NO ,bip.EX_CT AS PIECES ,bip.EX_WT AS GWT ,SUBSTRING(bip.CARGO_REFERENCE_NO, 16, 4) AS HSN ,SUBSTRING(bip.CARGO_REFERENCE_NO, 1, 11) AS MRN ,'QQ' AS LINE_CODE ,abnormal.VESSEL_FLIGHT ,bip.MBL_NO ,SUBSTRING(bip.CARGO_REFERENCE_NO, 12, 4) AS MSN ,bip.IN_PLAN_NO AS OD_JOB_NO ,REPLACE(bip.AR_DATE, '-', '') AS AR_DATE ,abnormal.ABNORMAL_CODE ,abnormal.PIECES AS PIECES_ABNORMAL ,abnormal.GWT AS GWT_ABNORMAL ,abnormal.DISC_WH_CODE ,abnormal.MRN AS MRN_ABNORMAL ,abnormal.MSN AS MSN_ABNORMAL ,abnormal.SEQ_NO_ID ,CONVERT(VARCHAR(8), abnormal.AR_DATE, 112) AS AR_DATE_ABNORMAL ,CASE abnormal.ABNORMAL_CODE WHEN 'MFN' THEN 2 ELSE 1 END AS SORT_SEQ_NO ,(SELECT OD_JOB_NO FROM TB_ECM_OD_ABNORMAL WHERE OD_JOB_NO = CONVERT(VARCHAR(20), bip.IN_PLAN_NO) AND SEQ_NO_ID = 1 AND SEND_DATE IS NULL) AS UPDATE_OD_JOB_NO FROM TB_BMS_IN_PLAN bip WITH (NOLOCK) INNER JOIN TB_ECM_OD_ABNORMAL abnormal ON abnormal.OD_JOB_NO = CONVERT(VARCHAR(20), bip.IN_PLAN_NO) AND abnormal.SEND_DATE IS NULL WHERE (
(abnormal.OD_JOB_NO = #{item.odJobNo} AND abnormal.SEQ_NO_ID = #{item.seqNoId})
) ORDER BY bip.IN_PLAN_NO, SORT_SEQ_NO

mapper.update:
/* CustomsMapper.updateSendAbnormalitiesReportd : 하기결과이상보고 신고 업데이트 */ UPDATE ad SET ad.ABNORMAL_DATE = DATEADD(HOUR, ${gmtTime}, GETDATE()) ,ad.ABNORMAL_MFN_DATE = CASE WHEN abnormal.ABNORMAL_CODE IN('MGN', 'SHT') THEN DATEADD(DAY, 15, abnormal.AR_DATE) ELSE NULL END
,ad.LAST_POD_STATUS = CASE WHEN ISNULL(ad.LAST_POD_STATUS, '') < 'ECM160' THEN 'ECM160' ELSE ad.LAST_POD_STATUS END
FROM TB_ECM_OD od INNER JOIN TB_ECM_OD_ABNORMAL abnormal ON abnormal.OD_JOB_NO = od.OD_JOB_NO AND abnormal.SEND_DATE IS NULL AND(
(abnormal.OD_JOB_NO = #{item.odJobNo} AND abnormal.SEQ_NO_ID = #{item.seqNoId})
) INNER JOIN TB_ECM_OD_ADDITIONAL ad ON ad.OD_JOB_NO = od.OD_JOB_NO WHERE od.MASTER_OD_JOB_NO IN(#{item.OD_JOB_NO});
UPDATE abnormal SET abnormal.SEND_DATE = DATEADD(HOUR, ${gmtTime}, GETDATE()) FROM TB_ECM_OD od INNER JOIN TB_ECM_OD_ABNORMAL abnormal ON abnormal.OD_JOB_NO = od.OD_JOB_NO AND abnormal.SEND_DATE IS NULL AND(
(abnormal.OD_JOB_NO = #{item.odJobNo} AND abnormal.SEQ_NO_ID = #{item.seqNoId})
) WHERE od.MASTER_OD_JOB_NO IN(#{item.OD_JOB_NO});

/* CustomsMapper.updateSendBmsInPlanAbnormalitiesReportd : 하기결과이상보고 신고 업데이트(반입예정데이터) */ UPDATE TB_ECM_OD_ABNORMAL SET SEND_DATE = DATEADD(HOUR, ${gmtTime}, GETDATE()) WHERE SEND_DATE IS NULL AND(
(OD_JOB_NO = #{item.odJobNo} AND SEQ_NO_ID = #{item.seqNoId})
)
